		const group = new Group();

		// Random spawn position around arena edge
		const angle = Math.random() * Math.PI * 2;
		group.position.set(
			Math.cos(angle) * SPAWN_DISTANCE,
			0,
			Math.sin(angle) * SPAWN_DISTANCE,
