				const cap = new Mesh(capGeo, snowMat.clone());
				cap.position.y = ld.y + ld.h * 0.4;
				tree.add(cap);
			}

			parent.add(tree);
		}
	}

	private buildLamps(parent: Group): void {
		const lampPositions = [
			{ x: -3, z: -7 },
			{ x: 3, z: -7 },
			{ x: -7, z: 0 },
			{ x: 7, z: 0 },
			{ x: -3, z: 7 },
