		for (let i = 0; i < this.auroraLights.length; i++) {
			const light = this.auroraLights[i];
			const phase = this.time * 0.3 + i * 1.5;
			light.intensity = 0.15 + Math.sin(phase) * 0.15;
			light.position.y = 12 + Math.sin(phase * 0.7) * 3;
		}
	}
