      "description": "outcome = result to achieve. behavior = action pattern to adopt. learning = skill to acquire (spaced study, user goals only). habit = recurring practice. maintenance = hold a standard. recovery = return from a setback. identity = who the user wants to become. exploratory = open-ended discovery.",
      "enum": [
        "outcome",
        "behavior",
        "learning",
        "habit",
        "maintenance",
        "recovery",
        "identity",
        "exploratory"
      ],
      "type": "string"
    },
    "limit": {
      "maximum": 100,
      "minimum": 1,
      "type": "integer"
    },
    "parent_goal_id": {
      "description": "The parent must be a top-level goal.",
      "type": "string"
    },
    "pushable": {
      "description": "For a user-goal update, set false when the user says to stop proactive brief pushes (reads still show briefs in the Goals tab).",
      "type": "boolean"
    },
    "query": {
      "description": "Terms to match against goal id, title, current_state, and description. Required for search.",
      "minLength": 2,
      "type": "string"
    },
    "reason": {
      "description": "Required for set_status. Concise user-facing explanation of why the lifecycle changed.",
      "minLength": 1,
      "type": "string"
    },
    "status": {
      "description": "The complete model-facing lifecycle for goals: active means the responsibility remains open, completed means it ended.",
      "enum": [
        "active",
        "completed"
      ],
      "type": "string"
    },
    "title": {
      "description": "Concise user-facing noun phrase naming the goal itself, not an instruction. Avoid generic leading verbs like `Track ...`; use concrete domain wording (`Wimbledon daily analysis`, `Childcare coordination`). Current activity and status go in current_state.",
      "type": "string"
    },
    "update_id": {
      "type": "string"
    },
    "value_alignment": {
      "type": "string"
    }
  },
  "required": [
    "action"
  ],
  "type": "object"
}
